from pathlib import Path
from urllib.parse import urlsplit
import json, html, re
P=Path(__file__).parent; D=P/'dist'; agents=json.loads((P/'agents.json').read_text())
try:(D/'realtors').resolve().relative_to(D.resolve())
except ValueError:
 raise ValueError('Profile directory outside dist') from None
if (D/'realtors').is_symlink():
 raise ValueError('Profile directory must not be a symlink')
slugs=set()
for a in agents:
 slug=a['slug']
 if not isinstance(slug,str) or not re.fullmatch(r'[a-z0-9]+(?:-[a-z0-9]+)*',slug):
  raise ValueError(f'Invalid profile slug: {slug!r}')
 if slug in slugs:raise ValueError(f'Duplicate profile slug: {slug}')
 slugs.add(slug)
 for fact in a['facts']:
  index=fact.get('source')
  if type(index) is not int or not 0<=index<len(a['sources']):
   raise ValueError(f"Invalid citation in {a['slug']}: {index!r}")
e=html.escape
DATE='October 3, 2026'
FAV="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='7' fill='%23102f28'/%3E%3Cpath d='M7 16 16 8 25 16v10H7z' fill='%23f2c341'/%3E%3Cpath d='M13 26v-8h6v8' fill='%23102f28'/%3E%3C/svg%3E"
def ext(url,label,cls=''):
 parsed=urlsplit(url)
 if parsed.scheme not in {'http','https'} or not parsed.netloc:
  raise ValueError(f'Invalid external URL: {url!r}')
 return f'<a href="{e(url)}" target="_blank" rel="noopener noreferrer" class="{cls}">{label}</a>'
def url(a): return '/realtors/'+a['slug']+'.html'
def head(title,description):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(description)}"><meta name="robots" content="noindex, nofollow"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:type" content="website"><link rel="icon" type="image/svg+xml" href="{FAV}"><link rel="stylesheet" href="/assets/site.css"></head><body><a class="skip" href="#main">Skip to content</a><div class="demo-bar"><span>EXAMPLE SITE</span> · Prepared for design review · Public sources reviewed {DATE}</div><header><div class="wrap header-in"><a class="brand" href="/"><span class="mark" aria-hidden="true">C</span><span>Cypress Realtor Guide<small>Cypress, Texas</small></span></a><nav aria-label="Main navigation"><a href="/#directory">The directory</a><a href="/#methodology">Our sources</a><a href="/#neighborhoods">Neighborhoods</a><a href="/#faq">FAQ</a></nav><a class="btn btn-gold" href="/#directory">Find a profile</a></div></header>'''
def footer():
 return f'''<footer><div class="wrap"><div class="footer-top"><div><a class="brand" href="/">Cypress Realtor Guide</a><p>An example website for design review. Profiles summarize linked public sources; the people and businesses shown have not been represented as endorsing this site. No paid partnership is asserted. Directory placement is not a performance ranking.</p></div><div class="footer-nav"><a href="/#directory">All profiles</a><a href="/#methodology">Sources &amp; standards</a><a href="/#privacy">Privacy</a></div></div><div class="footer-bottom"><span>Public sources reviewed {DATE} · A fixed research snapshot</span><span>Information may change. Confirm material details with the professional.</span></div></div></footer></body></html>'''
def profile(a):
 facts=''.join(f'<li>{e(f["text"])}<small>Source: {ext(a["sources"][f["source"]]["url"],e(a["sources"][f["source"]]["label"]))}</small></li>' for f in a['facts'])
 sources=''.join(f'<li>{ext(s["url"],e(s["label"]))}<br><span class="note">{e(s["supports"])}</span></li>' for s in a['sources'])
 related=''.join(f'<a href="{url(b)}">{e(b["name"])}</a>' for b in agents if b!=a)
 contact=f'<div><dt>Public business phone</dt><dd><a href="tel:{e(a["tel"])}">{e(a["phone"])}</a></dd></div>' if a.get('phone') else ''
 lic=f'<div><dt>License number listed by HAR</dt><dd>{e(a["license"])}</dd></div>' if a.get('license') else ''
 note='License numbers on this page are attributed to HAR, not a live TREC status check. ' if a.get('license') else ''
 return head(a['name']+' | Cypress Realtor Guide',a['intro'])+f'''<main id="main"><section class="profile-hero"><div class="wrap"><div class="breadcrumb"><a href="/">Home</a> / <a href="/#directory">Directory</a> / {e(a['name'])}</div><div class="profile-grid"><div><span class="eyebrow">{e(a['type'])} · Public-source profile</span><h1>{e(a['name'])}</h1><div class="brokerage">{e(a['brokerage'])}</div><p class="lede">{e(a['intro'])}</p><div class="hero-actions">{ext(a['official'], e(a.get('official_label','Visit official website')), 'btn btn-gold')}{ext(a['har'], 'View HAR profile', 'text-link')}</div><p class="notice">This is an example directory page, not an official website for {e(a['name'])}. Use the linked professional pages for current services, availability, and contact details.</p></div><aside class="profile-aside" aria-label="Professional details"><div class="monogram" aria-hidden="true">{e(a['initials'])}</div><span class="eyebrow">At a glance</span><dl><div><dt>Brokerage shown by public sources</dt><dd>{e(a['brokerage'])}</dd></div><div><dt>Profile type</dt><dd>{e(a['type'])}</dd></div>{lic}{contact}</dl>{ext(a['har'],'Check current public profile','btn btn-light')}<p class="note">{note}Sources reviewed {DATE}.</p></aside></div></div></section><section class="section"><div class="wrap profile-content"><div><span class="eyebrow">A closer look</span><h2>What the sources <em>say.</em></h2><ul class="fact-list">{facts}</ul><div class="profile-questions"><h3>Make your first conversation count.</h3><ul><li>What recent experience can you share with homes like mine in my target neighborhood?</li><li>Who would be my day-to-day contact, and how do you handle updates?</li><li>What services, fees, and representation terms would apply to my situation?</li></ul></div></div><aside class="sources"><h2>Sources &amp; context</h2><ol>{sources}</ol><p>These are public professional profiles and self-published business pages, not independently audited performance records. Ratings, review totals, sales volume, and comparative rankings are intentionally omitted.</p><p>Checked {DATE}. {note}For current licensing information, use {ext('https://www.trec.texas.gov/license-search/', 'TREC’s License Holder Search')}.</p></aside></div></section><section class="section" style="padding-top:0"><div class="wrap"><span class="eyebrow">Keep exploring</span><h2>Meet the other <em>professionals.</em></h2><div class="more-links">{related}</div></div></section></main>'''+footer()
team=next((a for a in agents if a['slug']=='lippincott-team'),None)
if team is None:
 raise ValueError("Required 'lippincott-team' profile not found in agents.json")
rows=''
for a in sorted(agents,key=lambda a:a['name'].removeprefix('The ')):
 rows+=f'''<article class="agent-row"><div class="monogram" aria-hidden="true">{e(a['initials'])}</div><div><h3><a href="{url(a)}" style="text-decoration:none">{e(a['name'])}</a></h3><div class="brokerage">{e(a['brokerage'])}</div>{ext(a['har'],'Source: HAR profile','text-link')}</div><p>{e(a['short'])}</p><a class="btn" href="{url(a)}" aria-label="View {e(a['name'])} profile">View profile</a></article>'''
hoods=[
 ('Master-planned community','Bridgeland','The developer describes an 11,500-acre community with lakes, trails, and connected villages.','https://www.bridgeland.com/community/','Official community guide'),
 ('Lake-centered living','Towne Lake','The community’s official site describes a 300-acre recreational lake and connected trails and waterways.','https://townelaketexas.com/lake','Official lake guide'),
 ('Community associations','Fairfield','The Fairfield website links residents to the Village, Central, Place, Village South, Lakes, and Trails association portals.','https://www.fairfieldvillage.org/','Official association portals'),
 ('Established in 1998','Coles Crossing','The community association describes a master-planned neighborhood off Highway 290 and Barker Cypress, with wooded recreational areas.','https://www.colescrossingcommunity.com/home/','Official community website'),
 ('Local association information','Cypress Creek Lakes','The property owners association provides community news, pool information, and contacts for its different phases.','https://cypresscreeklakeshoa.com/','Official association website')]
hoodcards=''.join(f'<article class="hood-card"><span class="eyebrow">{e(tag)}</span><h3>{e(name)}</h3><p>{e(copy)}</p>{ext(link,label,"text-link")}</article>' for tag,name,copy,link,label in hoods)
faqs=[
 ('Is this a ranking of the best agents?','No. It is a sourced directory adapted from a design concept. Profiles appear alphabetically, and the opening Lippincott Team placement demonstrates a featured layout. It does not establish a “best” agent or an independently scored winner.'),
 ('Is the featured placement sponsored?','No paid sponsorship or endorsement has been established for this example. The featured layout is a design demonstration. Any future paid relationship should be confirmed and clearly disclosed before the site is used as a live commercial guide.'),
 ('What was actually checked?','Names, brokerage affiliations, business contacts, and selected professional details were checked against the sources linked on each page. Some details are self-reported by the agents. This is not an audit of sales, reviews, reputation, or local knowledge.'),
 ('How current is the information?',f'Public sources were reviewed on {DATE}. The site is a fixed snapshot and does not update automatically. A linked source can itself be outdated; confirm current affiliation, licensing, services, and availability directly before relying on them.'),
 ('Can I contact an agent here?','Each profile links to the professional’s public website and HAR page. Where included, phone numbers are public business contacts from those sources. This example does not collect or forward inquiries; contact terms and any fees should be confirmed directly.'),
 ('Does this example collect my contact details?','There are no inquiry forms, email signups, or lead-submission features on this example. Outbound links open other sites, which have their own privacy practices. Site hosting and font services may process routine technical request information.')]
faq=''.join('<details'+(' id="privacy"' if i==5 else '')+f'><summary>{e(q)}</summary><p>{e(a)}</p></details>' for i,(q,a) in enumerate(faqs))
main=head('Cypress Realtor Guide | A sourced local directory','Explore seven Cypress-area real estate profiles, their public sources, and five neighborhood resources. An example site for design review.')+f'''<main id="main"><section class="hero"><div class="wrap"><div class="hero-grid"><div><span class="eyebrow">Cypress, Texas · Seven professional profiles</span><h1>Your next move starts with the <em>right conversation.</em></h1><p class="lede">Get to know seven real estate professionals and teams serving the Cypress area. Compare their public profiles, explore local communities, and bring better questions to your first call.</p><div class="hero-actions"><a class="btn btn-gold" href="#directory">Explore the directory</a><a class="text-link" href="#methodology">How we use sources</a></div></div><aside class="feature-card"><span class="tag">Featured profile · Example placement</span><div class="identity"><div class="monogram" aria-hidden="true">LT</div><div><h2>The Lippincott Team</h2><div class="brokerage">{e(team['brokerage'])}</div></div></div><p>{e(team['short'])}</p><a class="btn btn-gold" href="{url(team)}">Meet the team</a><p class="note">A featured layout, not a ranking or a paid-partnership claim. {ext(team['har'],'View the source profile')}.</p></aside></div><figure class="hero-photo"><img src="/assets/coles-crossing-morning.jpg" alt="Morning sunlight through mature trees beside the road at the western entrance to Coles Crossing in Cypress, Texas" width="4102" height="2328" fetchpriority="high"><figcaption><span>Coles Crossing, Cypress · Archival photograph, May 2014</span><span>{ext('https://commons.wikimedia.org/wiki/File:May_Morning_-_Flickr_-_pinemikey.jpg','Photo: Michael Martin')} · {ext('https://creativecommons.org/licenses/by-sa/2.0/','CC BY-SA 2.0')} · Cropped for display</span></figcaption></figure><div class="index-strip"><div><b>07</b><span>Individual profiles<br>with original sources</span></div><div><b>05</b><span>Community resources<br>to explore locally</span></div><div><b>01</b><span>Clear starting point<br>for your own research</span></div></div></div></section><section class="section" id="directory"><div class="wrap"><div class="section-intro"><div><span class="eyebrow">The directory · Alphabetical order</span><h2>Different people.<br>Your <em>personal fit.</em></h2></div><p>Open each profile for sourced details, official links, and public business contacts. This is a starting point for interviews, not a performance ranking.</p></div>{rows}</div></section><section class="section dark" id="methodology"><div class="wrap"><span class="eyebrow">Sources &amp; standards</span><h2>A useful guide starts with<br><em>being clear about the facts.</em></h2><div class="method-grid"><article><span class="step">01 / TRACE THE SOURCE</span><h3>Show where it came from.</h3><p>Each profile links to HAR and the professional’s own public pages. Brokerage details and selected background statements are attributed to those sources.</p></article><article><span class="step">02 / LEAVE OUT THE GUESSWORK</span><h3>Keep claims in proportion.</h3><p>Unverified sales totals, review counts, awards, and “best agent” claims have been left out. A self-published biography is treated as a biography, not an independent audit.</p></article><article><span class="step">03 / CHECK WHAT MATTERS</span><h3>Confirm before you commit.</h3><p>Public pages can change or lag behind reality. Check current licensing, brokerage, services, fees, and availability with the professional and relevant official sources.</p></article></div><p class="method-note">Reviewed {DATE}. No agent interviews, review audits, address-level knowledge tests, or comparative scoring were performed. Profiles are presented for your own research, without comparative scoring or endorsement.</p></div></section><section class="section" id="neighborhoods"><div class="wrap"><div class="section-intro"><div><span class="eyebrow">Five places to get oriented</span><h2>Start with the <em>neighborhood.</em></h2></div><p>Use these community and association websites to explore the details. School assignments, taxes, and restrictions should be checked for a specific property.</p></div><div class="hood-grid">{hoodcards}</div></div></section><section class="section" style="padding-top:0"><div class="wrap"><span class="eyebrow">Before the first call</span><h2>Bring questions that <em>matter to you.</em></h2><div class="question-grid"><article class="question-box"><span class="tag">If you’re selling</span><h3>Get specific about<br>the plan for <em>your home.</em></h3><ul><li>Which comparable sales would you use to discuss a list price?</li><li>What marketing, photography, and showing services are included?</li><li>How will we review buyer feedback and decide whether to adjust?</li></ul></article><article class="question-box"><span class="tag">If you’re buying</span><h3>Understand the process<br>before you <em>fall in love.</em></h3><ul><li>What experience do you have in the neighborhoods I’m considering?</li><li>How will we check property-specific taxes, restrictions, and other costs?</li><li>What should I understand about representation and compensation before touring?</li></ul></article></div></div></section><section class="section faq" id="faq"><div class="wrap"><span class="eyebrow">A few fair questions</span><h2>Clear from the <em>start.</em></h2><div class="faq-list">{faq}</div></div></section><section class="final"><div class="wrap"><div><h2>Find someone you’d like to talk to.</h2><p>Read the profile. Check the sources. Make the conversation your own.</p></div><a class="btn" href="#directory">Browse all seven profiles</a></div></section></main>'''+footer()
profiles={f'{a["slug"]}.html':profile(a) for a in agents}
for output in [D/'index.html',D/'404.html']+[(D/'realtors'/name) for name in profiles]:
 if output.is_symlink():raise ValueError(f'Output is a symlink: {output.name}')
(D/'index.html').write_text(main)
for name,page in profiles.items(): (D/'realtors'/name).write_text(page)
(D/'404.html').write_text(head('Page not found | Cypress Realtor Guide','Return to the Cypress realtor directory.')+'<main id="main" class="wrap notfound"><h1>That page isn’t in the guide.</h1><p>Find all seven profiles on the directory page.</p><a class="btn btn-gold" href="/">Return to the guide</a></main>'+footer())
# dist/realtors contains generated profile HTML; keep other files and assets.
for old in (D/'realtors').glob('*.html'):
 if old.name not in profiles: old.unlink()
print(f'Generated home, {len(agents)} profiles, and a 404 page')
